"use client";

import { motion } from "framer-motion";
import { Globe, ShieldCheck, Zap, Cpu } from "lucide-react";

const clientLogos = [
  { name: "Technoinnovators", icon: Globe, color: "text-blue-500" },
  { name: "FirmX", icon: Zap, color: "text-amber-500" },
  { name: "ElestroPlus", icon: Cpu, color: "text-emerald-500" },
  { name: "Elite Design", icon: Globe, color: "text-purple-500" },
  { name: "Huge Labs", icon: ShieldCheck, color: "text-red-500" },
];

export default function TrustSection() {
  return (
    <section className="py-24 px-6 bg-[#030303] border-t border-white/5">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <h3 className="text-3xl md:text-4xl font-black text-white/40 uppercase tracking-[0.3em] font-outfit">
            Client Testimonials
          </h3>
        </div>

        <div className="flex flex-wrap justify-center items-center gap-12 md:gap-24 opacity-60">
          {clientLogos.map((client) => (
            <motion.div 
              key={client.name}
              whileHover={{ opacity: 1, scale: 1.1 }}
              className="flex items-center gap-3 transition-all cursor-pointer group"
            >
              <client.icon className={`w-8 h-8 ${client.color} group-hover:drop-shadow-[0_0_10px_rgba(255,255,255,0.2)]`} />
              <span className="text-xl md:text-2xl font-black text-white/80 group-hover:text-white tracking-tighter">
                {client.name}
              </span>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
